select coalesce(jsonb_agg(t.failed),'[]'::jsonb)as failures from (select 'shared:official:equipment:es:b3561afd4baeeaff9340d6cf' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b3561afd4baeeaff9340d6cf' and payload#>'{description}'=$verify_c667310c3c3c17d7$"Objeto · Precio base · Peso\nUtensilios de cocina · 2 pp · 1 lb\n\nUtensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_c667310c3c3c17d7$::jsonb and payload#>'{features}'=$verify_17df154811e76464$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Utensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_17df154811e76464$::jsonb and payload#>'{rules,definition,description}'=$verify_d91a6351d35012ce$[{"id":"official-table","rows":[["Utensilios de cocina","2 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Utensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_d91a6351d35012ce$::jsonb) union all select 'shared:official:equipment:es:b4e79a3cd24aec59f54d746c' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b4e79a3cd24aec59f54d746c' and payload#>'{features}'=$verify_b10dc0571e393288$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica está decorada con un estampado de ojos. Mientras la lleves puesta, obtendrás los siguientes beneficios: • La túnica te permite ver en todas las direcciones y tienes ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista. • Tienes visión en la oscuridad hasta 36 m. • Puedes ver criaturas y objetos invisibles, además de ver en el Plano Etéreo, hasta una distancia de 36 m.\n\nNo se puede hacer que los ojos de la túnica se cierren o aparten la mirada. Aunque tú hagas ambas cosas con tus propios ojos, no se considerará que lo estés haciendo mientras lleves puesta esta túnica.\n\nSi se lanza un conjuro luz sobre la túnica o un conjuro luz del día a 1,5 m o menos de ella, quedarás cegado durante 1 minuto. Al final de cada uno de tus turnos, podrás hacer una tirada de salvación de Constitución (con CD 11 para luz o CD 15 para luz del día) y, si la superas, dejarás de estar cegado.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b10dc0571e393288$::jsonb) union all select 'shared:official:equipment:es:b4f84e86590127efe768a95f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b4f84e86590127efe768a95f' and payload#>'{features}'=$verify_2f559f340aeab2a5$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. El bonificador aumenta a +3 cuando usas la maza para atacar a un autómata.\n\nSi sacas un 20 en una tirada de ataque con esta arma, el objetivo sufrirá 2d6 de daño contundente adicional o 4d6 de daño contundente adicional si es un autómata. Si a un autómata le quedan 25 puntos de golpe o menos tras sufrir este daño, será destruido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_2f559f340aeab2a5$::jsonb) union all select 'shared:official:equipment:es:b51442c4161640e2e7a37f88' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b51442c4161640e2e7a37f88' and payload#>'{features}'=$verify_9d7a8b13ac6a9095$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este objeto parece una caja de madera que mide 30 cm de largo, 15 cm de ancho y 15 cm de profundidad. Pesa 2 kg y flota. Puede abrirse para guardar objetos en su interior. Además, este objeto tiene tres palabras de activación y cada una requiere una acción para pronunciarla.\n\nLa primera hace que la caja se despliegue y forme un bote de 3 m de largo, 1,2 m de ancho y 60 cm de profundidad. Este bote tiene un par de remos, un ancla, un mástil y una vela latina. El bote puede alojar a cuatro criaturas Medianas con comodidad.\n\nLa segunda hace que la caja se despliegue y forme un barco de 7,2 m de largo, 2,4 m de ancho y 1,8 m de profundidad. Este barco posee una cubierta, bancadas de remo, cinco juegos de remos, un timón de espadilla, un ancla, un camarote de cubierta y un mástil con una vela cuadrada. El barco puede alojar a quince criaturas Medianas con comodidad.\n\nCuando la caja se convierte en una embarcación, adopta el peso de una embarcación de su tamaño y cualquier cosa que contuviera la caja permanece en su interior.\n\nLa tercera palabra de activación hace que se pliegue de nuevo y recupere su forma de caja, siempre y cuando no haya criaturas a bordo. Cualquier objeto que contenga la embarcación y no quepa en la caja permanecerá fuera de ella cuando se pliegue. Los que sí quepan en la caja permanecerán dentro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_9d7a8b13ac6a9095$::jsonb) union all select 'shared:official:equipment:es:b516b1395030f3d0e44512e6' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b516b1395030f3d0e44512e6' and payload#>'{features}'=$verify_e9cf38e8596f211e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tubo de metal hueco mide alrededor de 30 cm de largo y pesa 0,5 kg. Como acción, puedes tocarlo y apuntar con él hacia un objeto que esté a 36 m o menos de ti que se pueda abrir, como una puerta, una tapa o una cerradura. El carillón emite un tono nítido y una cerradura o cerrojo del objeto se abrirá salvo que el sonido no pueda alcanzarlo. Si no queda ninguna cerradura o cierre, el objeto mismo se abrirá.\n\nEl carillón puede utilizarse diez veces. Tras el décimo uso, se resquebraja y se vuelve inútil.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e9cf38e8596f211e$::jsonb) union all select 'shared:official:equipment:es:b53f1d3eda845184553e548c' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b53f1d3eda845184553e548c' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_84965bf2bdfe287b$[{"id":"official-base-table","rows":[["Dardo","5 pc","0.25 lb","1d4 perforante","+0","Sutil, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_84965bf2bdfe287b$::jsonb) union all select 'shared:official:equipment:es:b55296bd6257b7ae74153624' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b55296bd6257b7ae74153624' and payload#>'{description}'=$verify_3bade0ddf6f5d7f7$"Objeto · Precio base · Peso\nCuerda de seda (50 pies) · 10 po · 5 lb\n\nCuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_3bade0ddf6f5d7f7$::jsonb and payload#>'{features}'=$verify_be24ea40c71d093b$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_be24ea40c71d093b$::jsonb and payload#>'{rules,definition,description}'=$verify_7901198c794c897c$[{"id":"official-table","rows":[["Cuerda de seda (50 pies)","10 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_7901198c794c897c$::jsonb) union all select 'shared:official:equipment:es:b6c252fadf815e5461e8d2a1' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b6c252fadf815e5461e8d2a1' and payload#>'{features}'=$verify_6a02f799c3d2ea30$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El frasco de esta poción parece vacío, pero, al mismo tiempo, da la impresión de contener líquido. Cuando la bebas, te volverás invisible durante 1 hora. Cualquier cosa que vistas o lleves será invisible también. El efecto acabará antes de tiempo si atacas o lanzas un conjuro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6a02f799c3d2ea30$::jsonb) union all select 'shared:official:equipment:es:b70bcbd36262a7a83ce6943f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b70bcbd36262a7a83ce6943f' and payload#>'{features}'=$verify_a20158e61a77c8ee$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto de “reducir” del conjuro agrandar/reducir durante 1d4 horas (no requiere concentración). El color rojo del líquido de la poción se contrae continuamente hasta quedar reducido a una gota diminuta y, a continuación, se expande para teñir el líquido transparente que la rodea. Si agitas la botella, no se interrumpirá el proceso.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_a20158e61a77c8ee$::jsonb) union all select 'shared:official:equipment:es:b70c41be552f3dc614f1f4ad' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b70c41be552f3dc614f1f4ad' and payload#>'{features}'=$verify_8cb44176861add58$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, obtendrás un bonificador de +1 a la CA. También puedes usar una acción adicional para pronunciar la palabra de activación y hacer que la armadura adopte el aspecto de una vestimenta normal o de otro tipo de armadura. Tú decides su apariencia, incluidos el color, estilo y accesorios, pero la armadura mantiene su peso y tamaño normales. La apariencia ilusoria dura hasta que emplees esta propiedad de nuevo o te quites la armadura.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_8cb44176861add58$::jsonb) union all select 'shared:official:equipment:es:b730d94858e9db458b9f67f2' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b730d94858e9db458b9f67f2' and payload#>'{description}'=$verify_1c0d2a3f4c2897ea$"Objeto · Precio base · Peso\nEstuche para mapas o pergaminos · 1 po · 1 lb\n\nEstuche para mapas o pergaminos. Esta caja de cuero cilíndrica puede contener hasta diez hojas de papel o cinco hojas de pergamino, enrolladas en ambos casos.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_1c0d2a3f4c2897ea$::jsonb and payload#>'{features}'=$verify_73d8460653650a2f$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estuche para mapas o pergaminos. Esta caja de cuero cilíndrica puede contener hasta diez hojas de papel o cinco hojas de pergamino, enrolladas en ambos casos.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_73d8460653650a2f$::jsonb and payload#>'{rules,definition,description}'=$verify_8784c36495e48939$[{"id":"official-table","rows":[["Estuche para mapas o pergaminos","1 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Estuche para mapas o pergaminos. Esta caja de cuero cilíndrica puede contener hasta diez hojas de papel o cinco hojas de pergamino, enrolladas en ambos casos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_8784c36495e48939$::jsonb) union all select 'shared:official:equipment:es:b87f89b4ff0c0569889ebd32' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b87f89b4ff0c0569889ebd32' and payload#>'{features}'=$verify_79d15a2b9ac643a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o todo el bonificador de la espada a tu Clase de Armadura en vez de usar el bonificador en los ataques de ese turno. Por ejemplo, puedes reducir el bonificador a tus tiradas de ataque y de daño a +1 y obtener un bonificador de +2 a tu CA. Los bonificadores ajustados permanecen en vigor hasta el principio de tu siguiente turno, aunque debes empuñar la espada para aprovechar el bonificador a la CA que confiere.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_79d15a2b9ac643a0$::jsonb) union all select 'shared:official:equipment:es:b8c8c1da43606dcf462e765f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b8c8c1da43606dcf462e765f' and payload#>'{description}'=$verify_346ce798f07d5474$"Objeto · Precio base · Peso\nCuerda de cáñamo (50 pies) · 1 po · 10 lb\n\nCuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_346ce798f07d5474$::jsonb and payload#>'{features}'=$verify_be24ea40c71d093b$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_be24ea40c71d093b$::jsonb and payload#>'{rules,definition,description}'=$verify_8cedde3dc4b4e343$[{"id":"official-table","rows":[["Cuerda de cáñamo (50 pies)","1 po","10 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_8cedde3dc4b4e343$::jsonb) union all select 'shared:official:equipment:es:b97890f2fdedbce0fbe843c2' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b97890f2fdedbce0fbe843c2' and payload#>'{features}'=$verify_8ee5d19ae1554acb$[{"id":"legacy-bonus-0","kind":"passive","name":"SpellAttackModifier","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador de +2 a las tiradas de ataque de hechizos y a las CD de las tiradas de salvación de tus hechizos.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno.\n\nSi eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas.\n\nEl talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_8ee5d19ae1554acb$::jsonb) union all select 'shared:official:equipment:es:b98496842c9011838d19a5f5' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b98496842c9011838d19a5f5' and payload#>'{features}'=$verify_152647ecf02599bc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica está cubierta de parches de tela de diversas formas y colores. Mientras la lleves puesta, podrás utilizar una acción para quitar uno de los parches y hacer que se convierta en el objeto o criatura que representa. En cuanto hayas quitado el último parche, la túnica se volverá una prenda normal y corriente.\n\nLa túnica tiene dos de cada uno de los siguientes parches: • Daga. • Linterna de ojo de buey (llena y encendida). • Espejo de acero. • Vara de 3 m. • Cuerda de cáñamo (15 m, enrollada). • Saco.\n\nAdemás, la túnica tiene otros 4d4 parches. Tu GM elige los parches o los determina al azar.\n\n01–08 · Bolsa con 100 po\n09–15 · Cofre de plata (30 cm de largo, 15 cm de ancho y de alto) con un valor de 500 po\n16–22 · Puerta de hierro (hasta 3 m de ancho y 3 de alto, atrancada por el lado que elijas), que puedes colocar en una abertura que esté a tu alcance. Se adecuará al tamaño de la abertura y se instalará y afianzará ella sola\n23–30 · 10 gemas con un valor de 100 po cada una\n31–44 · Escalera de madera (7,2 m de largo)\n45–51 · Un caballo de monta con alforjas\n52–59 · Pozo (un cubo de 3 m de lado), que puedes colocar en el suelo a 3 m o menos de ti\n60–68 · 4 pociones de curación\n69–75 · Bote de remos (3,6 m de largo)\n76–83 · Pergamino con un conjuro de nivel 1 a 3\n84–90 · 2 mastines\n91–96 · Ventana (60 cm por 1,2 m, con una profundidad de hasta 60 cm), que puedes colocar en una superficie vertical que esté a tu alcance\n97–00 · Ariete portátil\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_152647ecf02599bc$::jsonb) union all select 'shared:official:equipment:es:bb14d0105c6f290c8ccf2eaa' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bb14d0105c6f290c8ccf2eaa' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_c506ffd3b50bb694$[{"id":"official-base-table","rows":[["Bastón","2 pp","4 lb","1d6 contundente","+0","Versátil","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_c506ffd3b50bb694$::jsonb) union all select 'shared:official:equipment:es:bbb14cd18a2f266a4b6f3921' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bbb14cd18a2f266a4b6f3921' and payload#>'{features}'=$verify_78cacd5c998f65d7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo está vinculado a uno de los cuatro Planos Elementales. Tu GM elige el plano o lo determina al azar.\n\nMientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del plano vinculado y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a ciertas propiedades en función del plano vinculado.\n\nEl anillo tiene 5 cargas. Recupera 1d4 +1 cargas empleadas cada día, al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17.\n\nAnillo de comandar elementales de agua. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de agua. Además, puedes permanecer de pie sobre superficies líquidas y andar por ellas como si fueran terreno firme. También puedes hablar y entender acuano.\n\nSi ayudas a matar a un elemental de agua mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Puedes respirar bajo el agua y obtienes una velocidad nadando igual a tu velocidad caminando. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: crear o destruir agua (1 carga), controlar agua (3 cargas), muro de hielo (3 cargas) o tormenta de hielo (2 cargas).\n\nAnillo de comandar elementales de aire. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de aire. Además, cuando caigas, descenderás 18 m por asalto y no sufrirás daño por la caída. También puedes hablar y entender aurano.\n\nSi ayudas a matar a un elemental de aire mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de relámpago. • Tienes una velocidad volando igual a tu velocidad caminando y puedes levitar. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: muro de viento (1 carga), ráfaga de viento (2 cargas) o relámpago en cadena (3 cargas).\n\nAnillo de comandar elementales de fuego. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de fuego. Además, tienes resistencia al daño de fuego. También puedes hablar y entender ígneo.\n\nSi ayudas a matar a un elemental de fuego mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Eres inmune al daño de fuego. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: bola de fuego (2 cargas), manos ardientes (1 carga) o muro de fuego (3 cargas).\n\nAnillo de comandar elementales de tierra. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de tierra. Además, puedes moverte por terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano.\n\nSi ayudas a matar a un elemental de tierra mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de ácido. • Puedes moverte a través de tierra sólida o roca como si estas superficies fueran terreno difícil. Si acabas tu turno en ellas, irás a parar al espacio sin ocupar más cercano en el que estuviste por última vez. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: moldear la piedra (2 cargas), muro de piedra (3 cargas) o piel pétrea (3 cargas).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_78cacd5c998f65d7$::jsonb) union all select 'shared:official:equipment:es:bbea1bc3b1ff5ee755a3fe51' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bbea1bc3b1ff5ee755a3fe51' and payload#>'{features}'=$verify_265f412dd9875685$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nAzote de gigantes (requiere sintonización). Debes llevar un cinturón de fuerza de gigante (cualquier variedad) y unos guanteletes de fuerza de ogro para sintonizarte con esta arma. La sinto- nización acaba inmediatamente si te quitas uno de estos objetos. Mientras tengas sintonización con esta arma y la empuñes, tu puntuación de Fuerza aumentará en 4 y podrá pasar de 20, pero no de 30. Si sacas un 20 en una tirada de ataque con esta arma contra un gigante, este deberá superar una tirada de salvación de Constitución con CD 17 o morirá.\n\nAdemás, el martillo tiene 5 cargas. Mientras tengas sintonización con él, podrás gastar 1 carga y hacer un ataque con arma a distancia con el martillo lanzándolo como si tuviera la propiedad “arrojadiza”, con un alcance normal de 6 m y un alcance largo de 18 m. Si el ataque impacta, el martillo suelta un trueno audible a 90 m. El objetivo y todas las criaturas que estén a 9 m o menos de él deberán superar una tirada de salvación de Constitución con CD 17 o quedarán aturdidos hasta el final de tu siguiente turno. El martillo recupera 1d4 + 1 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_265f412dd9875685$::jsonb) union all select 'shared:official:equipment:es:bc117e3bd0d7e4cdec3a735a' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bc117e3bd0d7e4cdec3a735a' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_d3a2252f1305a8f4$[{"id":"official-base-table","rows":[["Hacha de guerra","10 po","4 lb","1d8 cortante","+0","Versátil","1d10"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_d3a2252f1305a8f4$::jsonb) union all select 'shared:official:equipment:es:bcca7355919b0bf34749e140' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bcca7355919b0bf34749e140' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_91bbc635cf7a71cf$[{"id":"official-base-table","rows":[["Hacha a dos manos","30 po","7 lb","1d12 cortante","+0","Pesada, A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_91bbc635cf7a71cf$::jsonb) union all select 'shared:official:equipment:es:bd6b6d0bae53fcbd755d2486' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bd6b6d0bae53fcbd755d2486' and payload#>'{features}'=$verify_54a737b808cf4ff1$[{"id":"restrain-target","kind":"other","name":"Apresar con la red","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Red. Una criatura Grande o más pequeña que sea impactada por una red quedará apresada hasta ser liberada. Esta arma no tendrá efecto sobre objetivos sin forma definida o que sean de tamaño Enorme o mayor. Una criatura puede emplear su acción para hacer una prueba de Fuerza con CD 10. Si tiene éxito, podrá liberarse a sí misma o a otra criatura dentro de su alcance. Infligir 5 de daño cortante a la red (CA 10) también liberará a la criatura sin causarle daño alguno, pondrá fin al efecto y destruirá la red. Cuando utilices una acción, una acción adicional o una reacción para atacar con una red, solo podrás realizar un ataque, incluso aunque normalmente pudieras hacer más de uno.\n\nSolo un ataque por acción, acción adicional o reacción. Liberar con acción y Fuerza CD 10, o destruir la red (CA 10) con 5 de daño cortante. No se inflige ese daño a la criatura.\n\nDuración: Hasta ser liberada.\n\nAlcance: 5/15 pies.","showInActions":false}]$verify_54a737b808cf4ff1$::jsonb) union all select 'shared:official:equipment:es:bde6b27f011acff17c7ca62f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:bde6b27f011acff17c7ca62f' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_7e500960c7b4f5ff$[{"id":"official-base-table","rows":[["Espadón","50 po","6 lb","2d6 cortante","+0","Pesada, A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_7e500960c7b4f5ff$::jsonb) union all select 'shared:official:equipment:es:c28c2cb011feaf97fdd6402b' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c28c2cb011feaf97fdd6402b' and payload#>'{features}'=$verify_c80a079acd0d8cdc$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este collar, podrás respirar con normalidad en cualquier entorno y tendrás ventaja en las tiradas de salvación contra gases y vapores nocivos (como los efectos de nube aniquiladora y nube apestosa, venenos inhalados y ataques de aliento de algunos dragones).\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_c80a079acd0d8cdc$::jsonb) union all select 'shared:official:equipment:es:c3bb4e8b9c95693e77d45d7a' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c3bb4e8b9c95693e77d45d7a' and payload#>'{features}'=$verify_bf73e034b33008ab$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este ungüento negro y pegajoso parece denso y pesado en el recipiente, pero fluye rápidamente cuando se vierte. El aceite puede cubrir a una criatura Mediana o más pequeña, así como el equipo que vista o lleve. Se necesita un vial extra por cada categoría de tamaño por encima de Mediano. Aplicar el aceite lleva 10 minutos. La criatura afectada obtiene el efecto del conjuro libertad de movimiento durante 8 horas.\n\nDe forma alternativa, el aceite se puede verter en el suelo como acción y cubrirá un cuadrado de 3 m de lado que duplicará el efecto del conjuro grasa en la zona durante 8 horas.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_bf73e034b33008ab$::jsonb) union all select 'shared:official:equipment:es:c452c8155853d2ae14b93ee8' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c452c8155853d2ae14b93ee8' and payload#>'{features}'=$verify_54a737b808cf4ff1$[{"id":"restrain-target","kind":"other","name":"Apresar con la red","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Red. Una criatura Grande o más pequeña que sea impactada por una red quedará apresada hasta ser liberada. Esta arma no tendrá efecto sobre objetivos sin forma definida o que sean de tamaño Enorme o mayor. Una criatura puede emplear su acción para hacer una prueba de Fuerza con CD 10. Si tiene éxito, podrá liberarse a sí misma o a otra criatura dentro de su alcance. Infligir 5 de daño cortante a la red (CA 10) también liberará a la criatura sin causarle daño alguno, pondrá fin al efecto y destruirá la red. Cuando utilices una acción, una acción adicional o una reacción para atacar con una red, solo podrás realizar un ataque, incluso aunque normalmente pudieras hacer más de uno.\n\nSolo un ataque por acción, acción adicional o reacción. Liberar con acción y Fuerza CD 10, o destruir la red (CA 10) con 5 de daño cortante. No se inflige ese daño a la criatura.\n\nDuración: Hasta ser liberada.\n\nAlcance: 5/15 pies.","showInActions":false}]$verify_54a737b808cf4ff1$::jsonb) union all select 'shared:official:equipment:es:c4b8e1f94de27d059f3e601b' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c4b8e1f94de27d059f3e601b' and payload#>'{features}'=$verify_0466a02893c255df$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, serás inmune a la magia que permita a otras criaturas leer tus pensamientos, determinar si mientes, saber tu alineamiento o averiguar tu tipo de criatura. Otras criaturas solo podrán comunicarse telepáticamente contigo si se lo permites.\n\nPuedes utilizar una acción para hacer que el anillo se vuelva invisible hasta que utilices otra acción para volverlo visible, hasta que te lo quites o hasta que mueras.\n\nSi mueres mientras llevas puesto el anillo, tu alma entrará en él salvo que ya albergue otra alma. Puedes permanecer en el anillo o partir al más allá. Mientras tu alma se encuentre en el anillo, podrás comunicarte telepáticamente con cualquier criatura que lo lleve puesto. Quien lo utilice no podrá evitar esta comunicación telepática.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_0466a02893c255df$::jsonb) union all select 'shared:official:equipment:es:c50d2ef062b71da3a562d1f3' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c50d2ef062b71da3a562d1f3' and payload#>'{features}'=$verify_1bd8f19edcfec44b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, tu velocidad caminando será de 9 m, salvo que normalmente fuera superior. Esta velocidad no se reduce si vas cargado o llevas una armadura pesada. Además, puedes saltar el triple de la distancia normal, pero nunca más lejos que lo que permita tu movimiento restante.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1bd8f19edcfec44b$::jsonb) union all select 'shared:official:equipment:es:c5b127456eacb42e3226696a' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c5b127456eacb42e3226696a' and payload#>'{features}'=$verify_cfaea569d2e0b0bc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, el arma ignora la resistencia al daño cortante.\n\nCuando ataques a una criatura que tenga al menos una cabeza con esta arma y el resultado de la tirada de ataque sea 20, cercenarás una de las cabezas de esa criatura. La criatura muere si no puede sobrevivir sin la cabeza perdida. Una criatura es inmune a este efecto si tiene inmunidad al daño cortante, no tiene o no necesita una cabeza, tiene acciones legendarias o tu GM decide que la criatura es demasiado grande como para que esta arma le corte la cabeza. En su lugar, una criatura así recibirá 6d8 de daño cortante adicional por el impacto.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_cfaea569d2e0b0bc$::jsonb) union all select 'shared:official:equipment:es:c6929be1c3c6f588eeadcd62' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c6929be1c3c6f588eeadcd62' and payload#>'{features}'=$verify_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$verify_49e3e80c25fd1c94$::jsonb) union all select 'shared:official:equipment:es:c6a9b98b612f27c0d1503b17' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c6a9b98b612f27c0d1503b17' and payload#>'{features}'=$verify_4e1d536c18987fb6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Si la piedra está tocando el suelo, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de tierra, como si hubieras lanzado conjurar elemental. La piedra no puede volver a emplearse de esta manera hasta el siguiente amanecer. La piedra pesa 2,5 kg.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4e1d536c18987fb6$::jsonb) union all select 'shared:official:equipment:es:c7bd474b6e2f8bc12a428038' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c7bd474b6e2f8bc12a428038' and payload#>'{features}'=$verify_18e6126021f5b235$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a una criatura con esta arma mágica y saques un 20 en la tirada de ataque, el objetivo sufrirá 3d6 de daño necrótico adicional si no es un autómata o un muerto viviente. Además, obtendrás una cantidad de puntos de golpe temporales igual al daño adicional infligido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_18e6126021f5b235$::jsonb) union all select 'shared:official:equipment:es:c7cb954c8d7ea77c90cdd4cb' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c7cb954c8d7ea77c90cdd4cb' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_ff84cbbf5081858d$[{"id":"official-base-table","rows":[["Garrote","1 pp","2 lb","1d4 contundente","+0","Ligera"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_ff84cbbf5081858d$::jsonb) union all select 'shared:official:equipment:es:c854a59e028f50e24ed1d734' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:c854a59e028f50e24ed1d734' and payload#>'{features}'=$verify_6fb68522b9bd82ca$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, el terreno difícil no te costará movimiento adicional. Además, la magia no podrá reducir tu velocidad ni dejarte apresado o paralizado.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6fb68522b9bd82ca$::jsonb) union all select 'shared:official:equipment:es:cad362e9a0790605f65af7ae' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cad362e9a0790605f65af7ae' and payload#>'{features}'=$verify_e1efd99463b4d636$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, mientras tengas sintonización con ella, tus puntos de golpe máximos aumentan en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta hacha está maldita y, al sintonizarte con ella, te afectará la maldición. Mientras sufras la maldición, no querrás deshacerte voluntariamente del hacha y la mantendrás siempre a tu alcance. También tendrás desventaja en las tiradas de ataque con otras armas, a menos que no haya ningún enemigo que puedas ver u oír a 18 m o menos de ti.\n\nCuando una criatura hostil te haga daño, si tienes el hacha en tu posesión, deberás superar una tirada de salvación de Sabiduría con CD 15 o sucumbirás a una furia berserk. Mientras estés bajo sus efectos, deberás utilizar tu acción cada asalto para atacar a la criatura que tengas más cerca con el hacha. Si puedes realizar ataques adicionales como parte de la acción de atacar, los utilizarás para atacar a la siguiente criatura más próxima tras derrotar a tu objetivo actual. Si tienes varios objetivos posibles, atacarás a uno al azar. Seguirás en ese estado hasta que comiences tu turno y no haya criaturas que puedas ver u oír a 18 m o menos de ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e1efd99463b4d636$::jsonb) union all select 'shared:official:equipment:es:cb06ceb25f2b8c9a2ef8e087' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cb06ceb25f2b8c9a2ef8e087' and payload#>'{features}'=$verify_f05deeaf62894d19$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este frasco de cristal, de 7,5 cm de diámetro, contiene 1d4 + 1 dosis de una mezcla espesa que huele ligeramente a aloe. El frasco y su contenido pesan 250 g.\n\nComo acción, una dosis del ungüento puede tragarse o aplicarse en la piel. La criatura que la reciba recuperará 2d8 + 2 puntos de golpe, dejará de estar envenenada y se curará de cualquier enfermedad.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f05deeaf62894d19$::jsonb) union all select 'shared:official:equipment:es:cb25f6558815b4e93185bb43' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cb25f6558815b4e93185bb43' and payload#>'{description}'=$verify_e6013f2a47c339f3$"Objeto · Precio base · Peso\nPluma (para escribir) · 2 pc · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_e6013f2a47c339f3$::jsonb and payload#>'{rules,definition,description}'=$verify_d81ecc59fcab73d4$[{"id":"official-table","rows":[["Pluma (para escribir)","2 pc","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_d81ecc59fcab73d4$::jsonb) union all select 'shared:official:equipment:es:cb90976a4748db28834a8e62' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cb90976a4748db28834a8e62' and payload#>'{description}'=$verify_f6dd41d6d6cb54a8$"Objeto · Precio base · Peso\nHerramientas de herrero · 20 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f6dd41d6d6cb54a8$::jsonb and payload#>'{features}'=$verify_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_2b2bca0e5c7a5789$::jsonb and payload#>'{rules,definition,description}'=$verify_fffb5f0692bd7e5b$[{"id":"official-table","rows":[["Herramientas de herrero","20 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$verify_fffb5f0692bd7e5b$::jsonb) union all select 'shared:official:equipment:es:cbfbeb4aafdeb42aa1660850' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cbfbeb4aafdeb42aa1660850' and payload#>'{features}'=$verify_cb1746b6035208e3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +3 a las tiradas de ataque y de daño realizadas con él.\n\nEl bastón tiene 10 cargas. Cuando impactes con un ataque cuerpo a cuerpo con él, podrás gastar hasta 3 cargas. Por cada carga empleada, el objetivo recibirá 1d6 de daño de fuerza adicional. El bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en un bastón no mágico.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_cb1746b6035208e3$::jsonb) union all select 'shared:official:equipment:es:cc6d904679038c3cb3a54a64' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cc6d904679038c3cb3a54a64' and payload#>'{features}'=$verify_db5c645ac61c50c7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras sostengas este abanico, podrás utilizar una acción para lanzar ráfaga de viento (CD de salvación 13) desde él. Una vez utilizado, no debería volver a emplearse hasta el siguiente amanecer. Cada vez que se vuelva a utilizar hasta ese momento, habrá una probabilidad acumulativa del 20 % de que no funcione y se haga jirones inútiles y no mágicos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_db5c645ac61c50c7$::jsonb) union all select 'shared:official:equipment:es:cd01816f1e2741e749410128' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cd01816f1e2741e749410128' and payload#>'{features}'=$verify_6370f594d411e3b1$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Debes ser competente con instrumentos de viento para poder tocar esta flauta. Mientras tengas sinto- nización con ella, las ratas normales y las ratas gigantes serán indiferentes hacia ti y no te atacarán salvo que las amenaces o dañes.\n\nLa flauta tiene 3 cargas. Si utilizas una acción para tocarla, podrás utilizar una acción adicional y gastar de 1 a 3 cargas para convocar un enjambre de ratas con cada carga empleada, siempre y cuando haya suficientes ratas a 0,75 km o menos de ti para que las convoques de esta manera (según decida tu GM). Si no hay ratas suficientes para formar un enjambre, la carga se desperdiciará. Los enjambres convocados irán hacia la música por el camino más corto disponible, pero, por lo demás, no estarán bajo tu control. La flauta recupera 1d3 cargas empleadas cada día, al amanecer.\n\nCuando un enjambre de ratas que no esté bajo el control de otra criatura se acerque a 9 m o menos de ti mientras estés tocando la flauta, podrás realizar una prueba de Carisma contra una prueba de Sabiduría del enjambre. Si pierdes, el enjambre se comportará de forma normal y no caerá bajo el influjo de la música de la flauta durante las siguientes 24 horas. Si ganas, el enjambre caerá bajo el influjo de la música de la flauta y se volverá amistoso hacia tus compañeros y tú mientras sigas tocando la flauta cada asalto como acción. Un enjambre amistoso obedece tus órdenes. Si no le das ninguna orden a un enjambre amistoso, se defenderá, pero no realizará ninguna otra acción. Si un enjambre amistoso comienza su turno y no puede escuchar la música de la flauta, se acabará tu control sobre el enjambre, este se comportará de forma normal y no podrá caer bajo el influjo de la música de la flauta durante las siguientes 24 horas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6370f594d411e3b1$::jsonb) union all select 'shared:official:equipment:es:ce1d5cf7c2597a556c05a8f1' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:ce1d5cf7c2597a556c05a8f1' and payload#>'{features}'=$verify_e1efd99463b4d636$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, mientras tengas sintonización con ella, tus puntos de golpe máximos aumentan en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta hacha está maldita y, al sintonizarte con ella, te afectará la maldición. Mientras sufras la maldición, no querrás deshacerte voluntariamente del hacha y la mantendrás siempre a tu alcance. También tendrás desventaja en las tiradas de ataque con otras armas, a menos que no haya ningún enemigo que puedas ver u oír a 18 m o menos de ti.\n\nCuando una criatura hostil te haga daño, si tienes el hacha en tu posesión, deberás superar una tirada de salvación de Sabiduría con CD 15 o sucumbirás a una furia berserk. Mientras estés bajo sus efectos, deberás utilizar tu acción cada asalto para atacar a la criatura que tengas más cerca con el hacha. Si puedes realizar ataques adicionales como parte de la acción de atacar, los utilizarás para atacar a la siguiente criatura más próxima tras derrotar a tu objetivo actual. Si tienes varios objetivos posibles, atacarás a uno al azar. Seguirás en ese estado hasta que comiences tu turno y no haya criaturas que puedas ver u oír a 18 m o menos de ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e1efd99463b4d636$::jsonb) union all select 'shared:official:equipment:es:cf69ef489f5705da5fee89ad' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cf69ef489f5705da5fee89ad' and payload#>'{features}'=$verify_c875a6812fbbc44a$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, tendrás resistencia al daño de fuego.\n\nEl bastón tiene 10 cargas. Mientras lo empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: bola de fuego (3 cargas), manos ardientes (1 carga), muro de fuego (4 cargas).\n\nEl bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se ennegrece, se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_c875a6812fbbc44a$::jsonb) union all select 'shared:official:equipment:es:cf92c104e190056bf85689b9' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cf92c104e190056bf85689b9' and payload#>'{features}'=$verify_9b1069889606242f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Debes ser competente con instrumentos de viento para poder tocar esta flauta. Tiene 3 cargas. Puedes utilizar una acción para tocarla y gastar 1 carga para crear una melodía inquietante a la vez que fascinante. Todas las criaturas que estén a 9 m o menos de ti y te escuchen tocar deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Si lo deseas, todas las criaturas situadas en esa zona que no sean hostiles hacia a ti superarán automáticamente la tirada de salvación. Las criaturas que fallen la tirada de salvación podrán repetirla al final de cada uno de sus turnos y, si la superan, se librarán del efecto. Las criaturas que superen la tirada de salvación serán inmunes al efecto de esta flauta durante 24 horas. La flauta recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_9b1069889606242f$::jsonb) union all select 'shared:official:equipment:es:cfdfaf1c30544aca1b7b1c6b' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:cfdfaf1c30544aca1b7b1c6b' and payload#>'{features}'=$verify_1be94401f6a37d1a$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nConsciencia (rara). No puedes ser sorprendido mientras este romboide azul oscuro gire alrededor de tu cabeza.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1be94401f6a37d1a$::jsonb) union all select 'shared:official:equipment:es:d12a1e5c8d86194c4729fcff' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d12a1e5c8d86194c4729fcff' and payload#>'{features}'=$verify_cb379d78a5d12f39$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tu puntuación de Fuerza es de 19 mientras lleves estos guanteletes. No tienen ningún efecto si tu Fuerza ya es de 19 o más.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_cb379d78a5d12f39$::jsonb) union all select 'shared:official:equipment:es:d137ddfe32e465d25e312925' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d137ddfe32e465d25e312925' and payload#>'{features}'=$verify_35abc986f4488354$[{"id":"legacy-bonus-0","kind":"passive","name":"PassivePerception","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +5 a la Percepción Pasiva.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta vara posee una cabeza con reborde y las siguientes propiedades.\n\nAlerta. Mientras empuñes la vara, tendrás ventaja en las pruebas de Sabiduría (Percepción) y en las tiradas de iniciativa.\n\nConjuros. Mientras empuñes la vara, puedes utilizar una acción para lanzar uno de los siguientes conjuros desde ella: detectar el bien y el mal, detectar magia, detectar venenos y enfermedades o ver invisibilidad.\n\nAura protectora. Como acción, puedes clavar el extremo de la empuñadura en el suelo, tras lo cual la cabeza de la vara emitirá luz brillante en un radio de 18 m y luz tenue 18 m más allá. Siempre que tú y cualquier otra criatura que sea amistosa contigo os encontréis bajo la luz brillante, obtendréis un bonificador de +1 a la CA y a las tiradas de salvación. Además, podréis sentir la ubicación de cualquier criatura invisible hostil que también esté bajo la luz brillante.\n\nLa cabeza de la vara dejará de brillar y el efecto terminará después de 10 minutos o cuando una criatura utilice una acción para sacar la vara de suelo. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_35abc986f4488354$::jsonb) union all select 'shared:official:equipment:es:d194c1925cd7eed15e88f9d2' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d194c1925cd7eed15e88f9d2' and payload#>'{features}'=$verify_7b79f082bef1b2e7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer. Cuando falles una tirada de salvación de Destreza mientras lo lleves puesto, podrás utilizar tu reacción y gastar 1 de sus cargas para superar la tirada.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7b79f082bef1b2e7$::jsonb) union all select 'shared:official:equipment:es:d2420446c122e6d1d1ade566' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d2420446c122e6d1d1ade566' and payload#>'{description}'=$verify_558a95cebcb036e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nFlecha · 1 po · 1 lb · 20 · 0.05 · 5\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_558a95cebcb036e3$::jsonb and payload#>'{rules,definition,description}'=$verify_1086a208ec8f4634$[{"id":"official-table","rows":[["Flecha","1 po","1 lb","20","0.05","5"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_1086a208ec8f4634$::jsonb) union all select 'shared:official:equipment:es:d29807a264cc92b6ef5be271' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d29807a264cc92b6ef5be271' and payload#>'{features}'=$verify_32e18da2643e9df2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón tiene 10 cargas y recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, un enjambre de insectos engulle el bastón, lo destruye y luego se dispersa.\n\nConjuros. Mientras empuñes el bastón, podrás usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: insecto gigante (4 cargas), plaga de insectos (5 cargas).\n\nNube de insectos. Mientras empuñes el bastón, podrás usar una acción y gastar 1 carga para hacer que un enjambre de insectos voladores inofensivos cubra un radio de 9 m a tu alrededor. Los insectos permanecerán durante 10 minutos y convertirán el área en una zona muy oscura para todas las criaturas menos para ti. El enjambre se mueve contigo y se mantiene centrado en ti. Un viento de al menos 15 km/h dispersará al enjambre y pondrá fin al efecto.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_32e18da2643e9df2$::jsonb) union all select 'shared:official:equipment:es:d2a4db57f6b1c2d09cc9d4f6' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d2a4db57f6b1c2d09cc9d4f6' and payload#>'{features}'=$verify_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4ca76cc6ddf1af62$::jsonb) union all select 'shared:official:equipment:es:d2c9cf7c7304dbd37f8bc7e1' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d2c9cf7c7304dbd37f8bc7e1' and payload#>'{features}'=$verify_dc07da072c2b7578$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, obtienes un bonificador de +2 a la CA contra ataques a distancia. Este bonificador se suma al bonificador a la CA normal del escudo. Además, cuando una criatura realice un ataque a distancia contra un objetivo que esté a 1,5 m o menos de ti, podrás usar tu reacción para convertirte en el objetivo del ataque.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dc07da072c2b7578$::jsonb) union all select 'shared:official:equipment:es:d33208f224791802d5cc9023' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d33208f224791802d5cc9023' and payload#>'{description}'=$verify_fb0110dc01b844c7$"Objeto · Precio base · Peso\nMochila · 2 po · 5 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_fb0110dc01b844c7$::jsonb and payload#>'{rules,definition,description}'=$verify_467c0a803342b9d2$[{"id":"official-table","rows":[["Mochila","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_467c0a803342b9d2$::jsonb) union all select 'shared:official:equipment:es:d3916bc71ae13afb7a224244' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d3916bc71ae13afb7a224244' and payload#>'{description}'=$verify_57ad9bd72f8bcb37$"Objeto · Precio base · Peso\nAntorcha · 1 pc · 1 lb\n\nAntorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_57ad9bd72f8bcb37$::jsonb and payload#>'{features}'=$verify_de7c9fd07470e6fa$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_de7c9fd07470e6fa$::jsonb and payload#>'{rules,definition,description}'=$verify_5a4b49e76e85ed57$[{"id":"official-table","rows":[["Antorcha","1 pc","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_5a4b49e76e85ed57$::jsonb) union all select 'shared:official:equipment:es:d45091cecb894506094369a2' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d45091cecb894506094369a2' and payload#>'{features}'=$verify_e1677d9db3bc1981$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bonificador de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica negra o azul oscura lleva bordadas pequeñas estrellas blancas o plateadas. Mientras la lleves puesta, recibirás un bonificador de +1 a las tiradas de salvación.\n\nSeis de las estrellas, situadas en la parte superior delantera de la túnica, son especialmente grandes. Mientras lleves puesta esta túnica, podrás utilizar una acción para arrancar una de las estrellas y usarla para lanzar proyectil mágico como un conjuro de nivel 5. Cada día al amanecer, 1d6 estrellas arrancadas reaparecerán en la túnica.\n\nMientras lleves puesta la túnica, podrás utilizar una acción para entrar en el Plano Astral junto con todo lo que vistas o lleves. Permanecerás allí hasta que utilices una acción para volver al plano en el que estabas. Reaparecerás en el último espacio que ocupabas o, si el espacio ya está ocupado, en el espacio sin ocupar más cercano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e1677d9db3bc1981$::jsonb) union all select 'shared:official:equipment:es:d557752500840d78b5e905d8' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d557752500840d78b5e905d8' and payload#>'{features}'=$verify_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dd50717b3781ab10$::jsonb) union all select 'shared:official:equipment:es:d613ca81a782e29c124eff8f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d613ca81a782e29c124eff8f' and payload#>'{features}'=$verify_fbbab4029ece3564$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Mientras las lleves puestas, podrás ver mucho mejor de lo normal hasta una distancia de 30 cm. Tendrás ventaja en las pruebas de Inteligencia (Investigación) que dependan de la vista si examinas una zona o estudias un objeto que se encuentre a esa distancia o menos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_fbbab4029ece3564$::jsonb) union all select 'shared:official:equipment:es:d6f94e0376d1900f4c11bb8c' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d6f94e0376d1900f4c11bb8c' and payload#>'{description}'=$verify_61b09f21613118e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nPincho de hierro · 1 po · 5 lb · 10 · 0.5 · 10\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_61b09f21613118e3$::jsonb and payload#>'{rules,definition,description}'=$verify_ca94dda6590b5857$[{"id":"official-table","rows":[["Pincho de hierro","1 po","5 lb","10","0.5","10"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_ca94dda6590b5857$::jsonb) union all select 'shared:official:equipment:es:d81d22e38c3ddd4e620b5674' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d81d22e38c3ddd4e620b5674' and payload#>'{features}'=$verify_7a23c041d535fc2b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, recuperarás 1d6 puntos de golpe cada 10 minutos, siempre y cuando tengas al menos 1 punto de golpe. Si pierdes una parte del cuerpo, el anillo hace que te vuelva a crecer y recupere su funcionalidad completa tras 1d6 + 1 días si te mantienes con al menos 1 punto de golpe durante todo ese tiempo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7a23c041d535fc2b$::jsonb) union all select 'shared:official:equipment:es:d837a9dc165434a7ebb4b2bb' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d837a9dc165434a7ebb4b2bb' and payload#>'{features}'=$verify_62756aacf630eddf$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas herraduras de hierro vienen de cuatro en cuatro. Mientras cuatro de ellas estén fijadas a los cascos de un caballo o de una criatura similar, le permitirán moverse con normalidad mientras flota 10 cm por encima del suelo. Este efecto implica que la criatura puede cruzar o permanecer sobre superficies no sólidas o inestables, como agua y lava. Además, no deja huellas e ignora el terreno difícil. Asimismo, la criatura podrá moverse a velocidad normal durante 12 horas al día, como máximo, sin padecer cansancio por hacer marchas forzadas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_62756aacf630eddf$::jsonb) union all select 'shared:official:equipment:es:d853aa97a9cf8e6489371efd' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d853aa97a9cf8e6489371efd' and payload#>'{features}'=$verify_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ffeec24cc9187eb8$::jsonb) union all select 'shared:official:equipment:es:d857ec4ef6d77131aa567d47' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d857ec4ef6d77131aa567d47' and payload#>'{features}'=$verify_3f71c7203bce29d4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras arda un fuego en este brasero de latón, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de fuego, como si hubieras lanzado conjurar elemental. El brasero no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEl brasero pesa 2,5 kg.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_3f71c7203bce29d4$::jsonb) union all select 'shared:official:equipment:es:d8a3f2f409a708360ac1156f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d8a3f2f409a708360ac1156f' and payload#>'{features}'=$verify_ffc941d8b32c6a46$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nConjuros. Mientras empuñes la varita, podrás usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros (CD de salvación 17): inmovilizar monstruo (5 cargas) o inmovilizar persona (2 cargas).\n\nEscape asistido. Mientras empuñes la varita, podrás usar tu reacción para gastar 1 carga y obtener ventaja en una tirada de salvación que realices para evitar que te apresen o paralicen, o puedes emplear 1 carga para obtener ventaja en cualquier prueba que hagas para escapar de un agarre.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ffc941d8b32c6a46$::jsonb) union all select 'shared:official:equipment:es:d915713ec2c391e5dcf80714' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d915713ec2c391e5dcf80714' and payload#>'{description}'=$verify_5615c435e74bef0a$"Objeto · Precio base · Peso\nRaciones (1 día) · 5 pp · 2 lb\n\nRaciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_5615c435e74bef0a$::jsonb and payload#>'{features}'=$verify_6268396968fa5288$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_6268396968fa5288$::jsonb and payload#>'{rules,definition,description}'=$verify_f8f536bb79fb87b3$[{"id":"official-table","rows":[["Raciones (1 día)","5 pp","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_f8f536bb79fb87b3$::jsonb))t;